import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, discount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const firstLine = invoice.number ?? 'DRAFT';

  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;

  const lineLines = invoice.lines.map((line) => {
    const total = lineTotal(line);
    let lineTxt = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    const discountPercent = line.discountPercent ?? 0;
    if (discountPercent > 0) {
      const discountAmount = discount(line);
      lineTxt += ` (${discountPercent}% discount = ${formatEuros(discountAmount)})`;
    }
    return lineTxt;
  });

  const totals = invoiceTotals(invoice);
  const lines = [firstLine, customerName, ...lineLines];
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: ${formatEuros(totals.discount)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

