  assert.equal(r.value.status, 'draft');
  assert.ok(Array.isArray(r.value.lines));
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 50 }), 50);
  assert.equal(lineTotal({ qty: 100, unitPrice: 1299 }), 129900);
});

test('lineTotal returns an integer', () => {
  const total = lineTotal({ qty: 10, unitPrice: 9500 });
  assert.equal(Number.isInteger(total), true);
  assert.equal(total, 95000);
});

test('invoiceTotals calculates totals for a single line invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.total, 40375);
});

test('invoiceTotals calculates totals for a multi-line invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
