test('invoiceTotals includes discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 },
    ],
  });

  const totals = invoiceTotals(r.value);
  const line1Total = 5 * 8500;
  const line2Total = 3 * 9500;
  const line1Discount = Math.round(line1Total * 10 / 100);
  const line2Discount = Math.round(line2Total * 20 / 100);
  const afterDiscount = line1Total + line2Total - line1Discount - line2Discount;
  const expectedVAT = Math.round(afterDiscount * 21 / 100);

  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, line1Discount + line2Discount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

